package overlay

import (
	"fmt"

	jsonpatch "github.com/evanphx/json-patch/v5"
	"github.com/immuta/operations/apps/pack/internal/artifact"
	"k8s.io/apimachinery/pkg/util/json"
	"sigs.k8s.io/yaml"
)

func applyPatchesToDoc(patches []artifact.RFC6902Patch, docBytes []byte, relPath string) ([]byte, error) {
	// Convert patch structs to JSON bytes for the patch library
	patchBytes, err := json.Marshal(patches)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal patches for %s: %w", relPath, err)
	}

	// Create the JSON Patch object
	patch, err := jsonpatch.DecodePatch(patchBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to decode patches for %s: %w", relPath, err)
	}

	// Convert original YAML to JSON to apply the patch
	jsonContent, err := yaml.YAMLToJSON(docBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to convert %s to JSON: %w", relPath, err)
	}

	modifiedJSON, err := patch.Apply(jsonContent)
	if err != nil {
		return nil, fmt.Errorf("failed to apply patch to %s: %w", relPath, err)
	}

	// Convert back to YAML
	modifiedYAML, err := yaml.JSONToYAML(modifiedJSON)
	if err != nil {
		return nil, fmt.Errorf("failed to convert patched %s back to YAML: %w", relPath, err)
	}

	return modifiedYAML, nil
}

package cmd

// This file contains the CLI command for building artifacts: `pack build`.
// By default, it reads the manifest file from the current directory and builds the artifact.
// Usage: `pack build [flags]`
// flags:
//   -d, --directory   Directory containing the manifest file, default is the current directory
//   -r, --recursive   Recursively build artifacts in subdirectories
//   -o, --output      Output directory for the built artifact(s), default is the same directory as the manifest file(s)
//   -v, --variable    Set variables in key=value format (can be used multiple times)

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"

	"github.com/immuta/operations/apps/pack/internal/artifact"
	"github.com/immuta/operations/apps/pack/internal/oci"
	"github.com/immuta/operations/libs/clog"
	"github.com/urfave/cli/v3"
)

// NewBuildCommand creates a new CLI command for building artifacts
func NewBuildCommand() *cli.Command {
	return &cli.Command{
		Name:  "build",
		Usage: "Build Kubernetes manifests from kustomize overlays",
		Flags: []cli.Flag{
			&cli.StringFlag{
				Name:    "directory",
				Aliases: []string{"d"},
				Usage:   "Directory containing the manifest file, default is the current directory",
				Value:   ".",
			},
			&cli.BoolFlag{
				Name:    "recursive",
				Aliases: []string{"r"},
				Usage:   "Recursively build artifacts in subdirectories",
				Value:   false,
			},
			&cli.StringFlag{
				Name:    "output",
				Aliases: []string{"o"},
				Usage:   "Output directory for the built artifact(s), default is the same directory as the manifest file(s)",
				Value:   "",
			},
			&cli.StringSliceFlag{
				Name:    "set",
				Aliases: []string{"s"},
				Usage:   "Set variables in key=value format (can be used multiple times)",
			},
		},
		Action: buildAction,
	}
}

// buildAction is the action function for the `pack build` command.
func buildAction(ctx context.Context, c *cli.Command) error {
	directory := c.String("directory")
	recursive := c.Bool("recursive")
	output := c.String("output")
	variables := c.StringSlice("set")

	variableMap, err := parseVariables(variables)
	if err != nil {
		return fmt.Errorf("failed to parse variables: %w", err)
	}

	logger := clog.GetLoggerFromContext(ctx)
	if len(variableMap) > 0 {
		logger.DebugContext(ctx, "Parsed variables", "variables", variableMap)
	}
	if _, err := os.Stat(directory); os.IsNotExist(err) {
		logger.ErrorContext(ctx, "Directory does not exist", "directory", directory)
		return err
	}

	if recursive {
		logger.DebugContext(ctx, "recursive flag set", "directory", directory, "output", output)
		return buildRecursive(ctx, logger, directory, output, variableMap)
	}

	logger.DebugContext(ctx, "building single artifact", "directory", directory, "output", output)
	return buildSingle(ctx, logger, directory, output, variableMap)
}

// buildSingle builds a single artifact from the manifest file in the specified directory.
func buildSingle(ctx context.Context, logger *slog.Logger, directory string, output string, variableMap map[string]string) error {
	manifestPath := filepath.Join(directory, ".app.yaml")
	ctx = context.WithValue(ctx, ManifestPathContextKey, manifestPath)
	if _, err := os.Stat(manifestPath); os.IsNotExist(err) {
		logger.ErrorContext(ctx, "Manifest file was not found in this directory")
		return err
	}
	logger.DebugContext(ctx, "Found manifest file")

	manifestPath = filepath.Clean(manifestPath)
	file, err := os.ReadFile(manifestPath)
	if err != nil {
		logger.ErrorContext(ctx, "Failed to read manifest file", "error", err)
		return err
	}
	logger.DebugContext(ctx, "Read manifest file")

	artifactOpts := artifact.Opts{
		ManifestFilePath: manifestPath,
		Path:             directory,
		RegistryURL:      oci.DefaultOCIRegistryURL, // Not used in build
		OCIRef:           "latest",                  // Not used in build
		SourceRepo:       "",                        // Not used in build
	}

	manifest, err := artifact.NewManifest(file)
	if err != nil {
		logger.ErrorContext(ctx, "Failed to parse manifest file", "error", err)
		return err
	}
	logger.DebugContext(ctx, "Parsed manifest file")

	newFunc, exists := aInit[manifest.Kind]
	if !exists {
		logger.ErrorContext(ctx, "Unsupported manifest kind")
		return errors.New("unsupported manifest kind")
	}

	ctx = context.WithValue(ctx, ArtifactKindContextKey, manifest.Kind)
	ctx = context.WithValue(ctx, AppNameContextKey, manifest.Spec.App)
	ctx = context.WithValue(ctx, PhaseContextKey, manifest.Spec.Phase)
	ctx = context.WithValue(ctx, EnvContextKey, manifest.Target.Env)
	ctx = context.WithValue(ctx, ClusterNameContextKey, manifest.Target.ClusterName)
	logger.DebugContext(ctx, "Manifest kind matched")

	art, artErr := artifact.GetArtifact(ctx, newFunc, &artifactOpts, manifest)
	if artErr != nil {
		logger.ErrorContext(ctx, "Failed to create artifact", "error", artErr)
		return artErr
	}
	logger.DebugContext(ctx, "Created artifact")

	if buildErr := art.Build(ctx, variableMap); buildErr != nil {
		logger.ErrorContext(ctx, "Failed to build artifact", "error", buildErr)
		return buildErr
	}
	logger.DebugContext(ctx, "Built artifact successfully")

	outputPath := getOutputPath(directory, output, manifest)
	ctx = context.WithValue(ctx, OutputPathContextKey, outputPath)
	if writeErr := art.Write(ctx, outputPath); writeErr != nil {
		logger.ErrorContext(ctx, "Failed to write artifact", "error", writeErr)
		return writeErr
	}
	logger.InfoContext(ctx, "Artifact build complete")

	return nil
}

// buildRecursive walks through the directory and builds artifacts for each subdirectory when
// the --recursive (-r) flag is set. It skips directories that do not contain a manifest file.
func buildRecursive(ctx context.Context, logger *slog.Logger, directory string, output string, variableMap map[string]string) error {
	errorCount := 0
	ctx = context.WithValue(ctx, ErrorCountContextKey, errorCount)
	buildCount := 0
	ctx = context.WithValue(ctx, BuildCountContextKey, buildCount)

	err := filepath.Walk(directory, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			logger.ErrorContext(ctx, "Failed to walk directory", "error", err)
			return err
		}
		ctx = context.WithValue(ctx, CurrentPathContextKey, path)

		if !info.IsDir() {
			logger.DebugContext(ctx, "is not directory, skipping")
			return nil
		}

		manifestPath := filepath.Join(path, ".app.yaml")
		if _, err := os.Stat(manifestPath); os.IsNotExist(err) {
			logger.DebugContext(ctx, "Manifest file not found in directory, skipping")
			return nil
		}
		ctx = context.WithValue(ctx, ManifestPathContextKey, manifestPath)

		if buildErr := buildSingle(ctx, logger, path, output, variableMap); buildErr != nil {
			logger.ErrorContext(ctx, "Failed to build artifact", "error", buildErr)
			errorCount++
			ctx = context.WithValue(ctx, ErrorCountContextKey, errorCount)
			// continue even if one build fails
			return nil
		}

		buildCount++
		ctx = context.WithValue(ctx, BuildCountContextKey, buildCount)
		logger.DebugContext(ctx, "Recursive build successful")

		return nil
	})

	if err != nil {
		logger.ErrorContext(ctx, "Error walking directory", "error", err)
		return err
	}
	logger.DebugContext(ctx, "Recursive build complete")

	if errorCount > 0 {
		logger.ErrorContext(ctx, "Some artifacts failed to build")
		return fmt.Errorf("failed to build %d/%d artifacts", errorCount, errorCount+buildCount)
	}

	logger.InfoContext(ctx, "Recursive build completed without errors")
	return nil
}

// parseVariables parses a slice of key=value strings into a map[string]string
func parseVariables(variables []string) (map[string]string, error) {
	if len(variables) == 0 {
		return make(map[string]string), nil
	}

	variableMap := make(map[string]string)
	for _, variable := range variables {
		parts := strings.SplitN(variable, "=", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid variable format '%s': expected key=value", variable)
		}
		key := strings.TrimSpace(parts[0])
		value := strings.TrimSpace(parts[1])
		if key == "" {
			return nil, fmt.Errorf("invalid variable format '%s': key cannot be empty", variable)
		}
		if value == "" {
			return nil, fmt.Errorf("invalid variable format '%s': value cannot be empty", variable)
		}
		variableMap[key] = value
	}
	return variableMap, nil
}

// getOutputPath determines the output file path. If the output isn't specified, it defaults to
// the directory the manifest is in. If the output is a directory, it appends the generated file name.
func getOutputPath(directory string, output string, manifest *artifact.Manifest) string {
	fileName := genFileName(manifest.Spec.App, manifest.Target.ClusterName, manifest.Spec.Phase)

	if output == "" {
		return filepath.Join(directory, fileName)
	}

	if stat, err := os.Stat(output); err == nil && stat.IsDir() {
		return filepath.Join(output, fileName)
	}

	return output
}

// genFileName generates a file name based on the artifact metadata
func genFileName(app string, cluster string, phase string) string {
	return fmt.Sprintf("%s-%s-%s.pack.yaml", app, cluster, phase)
}

package overlay

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/immuta/operations/apps/pack/internal/artifact"
	"github.com/immuta/operations/libs/clog"
	"github.com/opencontainers/go-digest"
	"github.com/samber/lo"
	"sigs.k8s.io/kustomize/api/krusty"
	"sigs.k8s.io/kustomize/api/types"
	"sigs.k8s.io/kustomize/kyaml/filesys"
)

const (
	FileBackupExtension = ".bak"
)

var yamlSeparator = regexp.MustCompile(`(?m)^---$`)

// Overlay represents a kustomize overlay that can be built and used to generate Kubernetes manifests.
type Overlay struct {
	Manifest     *artifact.Manifest
	BuiltOverlay *[]byte
	logger       *slog.Logger
	Digest       digest.Digest
	Path         string
	RegistryURL  string
	OCIRef       string
	SourceRepo   string
}

// New creates a new Overlay instance by reading the manifest file and initializing the overlay properties.
// context is here for future error handling, but is not currently used.
func New(ctx context.Context, opts *artifact.Opts, manifest *artifact.Manifest) (artifact.Artifact, error) {
	return &Overlay{
		Manifest:    manifest,
		Path:        opts.Path,
		RegistryURL: opts.RegistryURL,
		OCIRef:      opts.OCIRef,
		SourceRepo:  opts.SourceRepo,
		logger:      clog.GetLoggerFromContext(ctx),
	}, nil
}

// Build processes the overlay using kustomize and stores the result in BuiltOverlay.
// It also computes the digest of the resulting YAML.
func (o *Overlay) Build(ctx context.Context, vars map[string]string) error {
	patches, err := artifact.ResolvePatches(o.Manifest, vars)
	if err != nil {
		o.logger.ErrorContext(ctx, "failed to resolve patches", "error", err)
		return err
	}

	// Validate patches, including multi-document file validation
	err = artifact.ValidatePatches(o.Manifest.Patches, o.Path)
	if err != nil {
		o.logger.ErrorContext(ctx, "patch validation failed", "error", err)
		return err
	}

	// Track backup files for cleanup at the end of the entire build process
	var backupFiles []string
	defer func() {
		// Always clean up backup files and restore originals after build is complete
		o.restoreOriginalFiles(ctx, backupFiles)
		o.logger.DebugContext(ctx, "restored original files", "files", backupFiles)
	}()

	backupFiles, err = o.applyPatches(ctx, patches)
	if err != nil {
		o.logger.ErrorContext(ctx, "failed to apply patches", "error", err)
		return err
	}

	// We want to use the default options, but we need to enable the Helm plugin
	// for some reason, HelmConfig.Command defaults to `helmV3` instead of `helm`, so we set it explicitly.
	kOpts := krusty.MakeDefaultOptions()
	kOpts.PluginConfig.HelmConfig.Enabled = true
	kOpts.PluginConfig.HelmConfig.Command = "helm"
	kOpts.LoadRestrictions = types.LoadRestrictionsNone
	k := krusty.MakeKustomizer(kOpts)
	fSys := filesys.MakeFsOnDisk()
	resMap, err := k.Run(fSys, o.Path)
	if err != nil {
		o.logger.ErrorContext(ctx, "failed to run kustomize", "error", err)
		return err
	}

	yamlBytes, err := resMap.AsYaml()
	if err != nil {
		o.logger.ErrorContext(ctx, "failed to convert kustomize build output to YAML", "error", err)
		return err
	}

	o.BuiltOverlay = &yamlBytes
	o.Digest = digest.FromBytes(yamlBytes)
	return nil
}

// Write writes the built overlay to a specified file path with metadata header comments.
func (o *Overlay) Write(ctx context.Context, filePath string) error {
	if o.BuiltOverlay == nil {
		o.logger.ErrorContext(ctx, "tried to write to disk, but built overlay is nil")
		return errors.New("tried to write to disk, but built overlay is nil")
	}

	// Prepare metadata for the header
	header, err := artifact.GenerateArtifactMetadata(o.Manifest)
	if err != nil {
		o.logger.ErrorContext(ctx, "failed to generate artifact metadata", "error", err)
		return err
	}

	// Combine header with the built YAML content
	finalContent := append(*header, *o.BuiltOverlay...)

	if writeErr := os.WriteFile(filePath, finalContent, 0600); writeErr != nil {
		o.logger.ErrorContext(ctx, "failed to write overlay to disk", "error", writeErr)
		return writeErr
	}
	return nil
}

// GetDigest returns the digest of the built overlay
func (o *Overlay) GetDigest() digest.Digest {
	return o.Digest
}

// GetBuild returns the built overlay data
func (o *Overlay) GetBuild() *[]byte {
	return o.BuiltOverlay
}

// GetMetadata returns metadata about the overlay as a map
func (o *Overlay) GetMetadata() *artifact.Metadata {
	return &artifact.Metadata{
		App:     o.Manifest.Spec.App,
		Phase:   o.Manifest.Spec.Phase,
		Version: o.OCIRef,
		Source:  o.SourceRepo,
	}
}

// GetPath returns the path of the overlay
func (o *Overlay) GetPath() string {
	return o.Path
}

// GetOCIRef returns the tag ref for the overlay
func (o *Overlay) GetOCIRef() string {
	return o.OCIRef
}

// applyPatches applies patches to files specified in the manifests using input variables.
// It traverses the overlay path and patches files as specified by the manifest. If the file has multiple documents,
// it groups patches by document index for efficient processing.
//
// Returns a list of backup file paths that need to be restored after the build process.
func (o *Overlay) applyPatches(ctx context.Context, patchesByFile map[string][]artifact.ResolvedPatch) ([]string, error) {
	o.logger.DebugContext(ctx, "applying patches")

	// Track backup files for caller to clean up after build
	var backupFiles []string

	for relPath, patches := range patchesByFile {
		var result bytes.Buffer
		filePath := filepath.Clean(filepath.Join(o.Path, relPath))
		backupPath := filepath.Clean(filePath + FileBackupExtension)

		o.logger.InfoContext(ctx, "applying patches", "file", relPath, "patches", patches)

		// Step 1: Read original file
		fileContent, err := os.ReadFile(filePath)
		if err != nil {
			return nil, fmt.Errorf("failed to read file %s: %w", relPath, err)
		}

		// Step 2: Create backup
		err = os.Rename(filePath, backupPath)
		if err != nil {
			return nil, fmt.Errorf("failed to create backup for file %s: %w", relPath, err)
		}
		backupFiles = append(backupFiles, backupPath)
		o.logger.DebugContext(ctx, "created backup", "original", filePath, "backup", backupPath)

		docStrings := removeEmptyLines(yamlSeparator.Split(strings.TrimSpace(string(fileContent)), -1))
		o.logger.DebugContext(ctx, "parsing yaml file", "file", relPath, "doc_count", len(docStrings))

		// Group patches by document index for efficient processing
		patchesByDocIndex := artifact.GroupPatchesByDocumentIndex(patches)

		for i, docString := range docStrings {
			o.logger.DebugContext(ctx, "parsing yaml doc", "file", relPath, "current_doc_index", i, "doc_string", docString)
			if docString == "" {
				o.logger.DebugContext(ctx, "skipping empty doc")
				continue
			}

			docBytes := []byte(docString)

			// Check if we have patches for this specific document index
			if patchesForDoc, exists := patchesByDocIndex[i]; exists {
				rfc6902PatchesForDoc := artifact.ExtractRFC6902Patches(patchesForDoc)

				o.logger.DebugContext(ctx, "document has patches", "file", relPath, "current_doc_index", i, "patches", rfc6902PatchesForDoc)
				docBytes, err = applyPatchesToDoc(rfc6902PatchesForDoc, docBytes, relPath)
				if err != nil {
					o.logger.ErrorContext(ctx, "failed to apply patches to doc", "path", relPath, "current_doc_index", i, "error", err)
					return nil, err
				}
			}

			_, wsErr := result.WriteString("---\n")
			if wsErr != nil {
				o.logger.ErrorContext(ctx, "failed to write yaml separator to buffer", "path", relPath, "error", wsErr)
				return nil, wsErr
			}

			_, wErr := result.Write(docBytes)
			if wErr != nil {
				o.logger.ErrorContext(ctx, "failed to write patched document to buffer", "path", relPath, "current_doc_index", i, "error", wErr)
				return nil, wErr
			}
		}

		// Step 3: Write patched file (original will be restored in defer)
		err = os.WriteFile(filePath, result.Bytes(), 0640)
		if err != nil {
			return nil, fmt.Errorf("failed to write patched file %s: %w", relPath, err)
		}

		o.logger.DebugContext(ctx, "successfully patched file", "relative_path", relPath)
	}

	return backupFiles, nil
}

// restoreOriginalFiles restores original files from their .bak backups and cleans up backup files.
// This ensures the file system is left in its original state after patching and building.
func (o *Overlay) restoreOriginalFiles(ctx context.Context, backupFiles []string) {
	for _, backupPath := range backupFiles {
		originalPath := strings.TrimSuffix(backupPath, FileBackupExtension)

		o.logger.DebugContext(ctx, "cleaning up patched file", "path", backupPath)
		err := os.Remove(originalPath)
		if err != nil {
			o.logger.WarnContext(ctx, "failed to remove patched file during restore", "original", originalPath, "error", err)
			// Continue anyway to try restoring backup
		}

		o.logger.DebugContext(ctx, "restoring file", "original_path", originalPath)
		err = os.Rename(backupPath, originalPath)
		if err != nil {
			o.logger.WarnContext(ctx, "failed to restore backup file", "backup", backupPath, "original", originalPath, "error", err)
		} else {
			o.logger.DebugContext(ctx, "restored original file", "backup", backupPath, "original", originalPath)
		}
	}
}

func removeEmptyLines(docStrings []string) []string {
	lines := lo.Filter(docStrings, func(line string, _ int) bool {
		return line != ""
	})
	return lines
}

package artifact

import (
	"context"
	"time"

	"github.com/opencontainers/go-digest"
	"github.com/samber/lo"
)

// NewFunc defines the signature for a function that creates a new Artifact instance
// It returns an Artifact and an error, but currently we're not doing any error handling
// on Overlay creation, so the error is always nil. It's part of the interface to allow for future extensibility.
type NewFunc func(ctx context.Context, opts *Opts, manifest *Manifest) (Artifact, error)

// Artifact defines the interface for a Kubernetes artifact that can be built and written to disk
type Artifact interface {
	Build(context.Context, map[string]string) error
	Write(context.Context, string) error
	GetDigest() digest.Digest
	GetBuild() *[]byte
	GetMetadata() *Metadata
	GetPath() string
	GetOCIRef() string
}

type Metadata struct {
	App     string
	Phase   string
	Version string
	Source  string
}

type Opts struct {
	ManifestFilePath string
	Path             string
	RegistryURL      string
	OCIRef           string
	SourceRepo       string
}

func GetArtifact(ctx context.Context, newFunc any, opts *Opts, manifest *Manifest) (Artifact, error) {
	fn, ok := newFunc.(func(ctx context.Context, opts *Opts, manifest *Manifest) (Artifact, error))
	if !ok {
		panic("GetArtifact - newFunc does not match the expected signature")
	}

	art, err := fn(ctx, opts, manifest)
	if err != nil {
		return nil, err
	}
	return art, nil
}

type ResolvedPatch struct {
	Target *PatchTarget `json:"-"`
	Patch  RFC6902Patch
}

type RFC6902Patch struct {
	Value any    `json:"value,omitempty"`
	Op    string `json:"op"`
	Path  string `json:"path"`
}

func ExtractRFC6902Patches(patches []ResolvedPatch) []RFC6902Patch {
	return lo.Map(patches, func(resolvedPatch ResolvedPatch, _ int) RFC6902Patch {
		return resolvedPatch.Patch
	})
}

// GroupPatchesByDocumentIndex groups patches by their target document index for efficient processing.
// Patches without a target default to document index 0.
func GroupPatchesByDocumentIndex(patches []ResolvedPatch) map[int][]ResolvedPatch {
	return lo.GroupBy(patches, func(patch ResolvedPatch) int {
		// Default to the first document (index 0) if no target is specified. We never actually use this default
		// because we fail fast if no target is specified, but we need to return an int
		if patch.Target != nil && patch.Target.DocumentIndex != nil {
			return *patch.Target.DocumentIndex
		}
		return 0
	})
}

// IsValidRFC3339 checks if a timestamp string is a valid RFC3339 format.
func IsValidRFC3339(timestamp string) bool {
	_, err := time.Parse(time.RFC3339, timestamp)
	return err == nil
}

package artifact

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/samber/lo"
	"gopkg.in/yaml.v3"
)

// Manifest defines the structure of the `.app.yaml` manifest file that pack consumes to build and push artifacts
type Manifest struct {
	// Kind maps to an implementation of the Artifact interface. One of: `KustomizeApp`
	Kind    string  `yaml:"kind" json:"kind"`
	Spec    Spec    `yaml:"spec" json:"spec"`
	Target  Target  `yaml:"target" json:"target"`
	Patches []Patch `yaml:"patches,omitempty" json:"patches,omitempty"`
}

// Spec defines the artifact metadata
type Spec struct {
	// App is the name of the application. If OCIRepo is not specified, this will be the Harbor project name that the build overlays will be pushed to.
	App string `yaml:"app" json:"app"`

	// Phase is the deployment phase that the artifact represents.
	// This is currently required, but as more artifacts become supported, this will only be required where it makes
	// sense.
	Phase string `yaml:"phase" json:"phase"`

	// OCIRepo is an optional way to specify the Harbor project name that you want to push to if you don't want to use App.
	OCIRepo string `yaml:"ociRepo,omitempty" json:"ociRepo,omitempty"`

	// SourcePaths is an optional list of source repository paths that are relevant to this app.
	// Used by `pack cd` to scope the changelog to commits that touched these paths.
	SourcePaths []string `yaml:"sourcePaths,omitempty" json:"sourcePaths,omitempty"`
}

// Target describes where the artifact will be deployed.
type Target struct {
	// Env is the deployment environment. One of: `prod`, `nonprod`
	Env string `yaml:"env" json:"env"`

	// GlobalSegment is the identifier for the SaaS Global Segment the service is deployed to. One of: `ap`, `eu`, `na`, `plat`
	GlobalSegment string `yaml:"globalSegment" json:"globalSegment"`

	// ClusterName is the name of the Kubernetes cluster the service is deployed to.
	ClusterName string `yaml:"clusterName" json:"clusterName"`
}

// Patch represents an RFC 6902 JSON Patch operation to be applied to a file.
type Patch struct {
	// Target is an optional selector for the target. In YAML, this is used for multi-document files.
	Target *PatchTarget `yaml:"target,omitempty" json:"target,omitempty"`

	// File is the name of the file the patch will be applied to.
	File string `yaml:"file" json:"file"`

	// Op should map to RFC 6902 JSON Patch operation values: "add", "remove", "replace", "move", "copy", "test".
	Op string `yaml:"op" json:"op"`

	// Path follows the RFC 6902 JSON Patch path format (e.g., "/spec/template/spec/containers/0/image").
	Path string `yaml:"path" json:"path"`

	// ValueVariable is a string that will be replaced with the actual value at build time.
	ValueVariable string `yaml:"valueVariable" json:"valueVariable"`
}

// PatchTarget selects a document by its zero-based index.
type PatchTarget struct {
	// DocumentIndex specifies the document to select in a multi-document YAML file. It's a pointer to distinguish
	// between explicitly selecting the first document (`0`), and not selecting anything (`nil`).
	DocumentIndex *int `yaml:"documentIndex,omitempty" json:"documentIndex,omitempty"`
}

// NewManifest unmarshalls the raw bytes of the `.app.yaml` file into a *Manifest.
func NewManifest(manifestFile []byte) (*Manifest, error) {
	manifest := &Manifest{}
	err := yaml.Unmarshal(manifestFile, manifest)
	if err != nil {
		return nil, err
	}

	return manifest, nil
}

// ConstructURI generates a URI that references an OCI artifact in the following format:
//
// <REGISTRY_URL>/<REPO>/deploy/<CLUSTER_NAME>/<PHASE>
//
// If the manifest specifies an OCIRepo, the repo path will be <OCIRepo>/<app>,
// otherwise it will just be <app>.
//
// Examples:
//   - registry.ic-ops.net/audit/deploy/eks-saas-nonprod-use1-1/staging
//   - registry.ic-ops.net/my-repo/marketplace/deploy/eks-saas-prod-use1-jpmc/prod
func ConstructURI(registryURL string, manifest *Manifest) string {
	repo := manifest.Spec.App
	if manifest.Spec.OCIRepo != "" {
		repo = fmt.Sprintf("%s/%s", manifest.Spec.OCIRepo, manifest.Spec.App)
	}

	return fmt.Sprintf("%s/%s/deploy/%s/%s",
		registryURL,
		repo,
		manifest.Target.ClusterName,
		manifest.Spec.Phase,
	)
}

// GenerateArtifactMetadata generates the metadata as a comment that is prepended to the YAML manifest.
func GenerateArtifactMetadata(manifest *Manifest) (*[]byte, error) {
	if manifest == nil {
		return nil, errors.New("manifest cannot be nil")
	}
	timestamp := time.Now().UTC().Format(time.RFC3339)
	metadataJSON, err := json.Marshal(manifest)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal metadata: %w", err)
	}

	header := fmt.Sprintf(`# %s
# %s
---
`, timestamp, string(metadataJSON))

	headerBytes := []byte(header)
	return &headerBytes, nil
}

// HasEmptyFields checks if the manifest has any empty required fields and returns specific errors.
func HasEmptyFields(manifest Manifest) error {
	emptyFields := lo.Filter([]struct {
		field string
		value string
	}{
		{"kind", manifest.Kind},
		{"spec.app", manifest.Spec.App},
		{"spec.phase", manifest.Spec.Phase},
		{"target.clusterName", manifest.Target.ClusterName},
	}, func(item struct {
		field string
		value string
	}, _ int) bool {
		return item.value == ""
	})

	if len(emptyFields) == 0 {
		return nil
	}

	fieldNames := lo.Map(emptyFields, func(item struct {
		field string
		value string
	}, _ int) string {
		return item.field
	})

	if len(fieldNames) == 1 {
		return fmt.Errorf("required field '%s' cannot be empty", fieldNames[0])
	}

	return fmt.Errorf("required fields cannot be empty: %s", strings.Join(fieldNames, ", "))
}

// ValidatePatches validates that all patches have valid ops and paths.
// If basePath is provided, it also validates that patches for multi-document YAML files have explicit document targets.
func ValidatePatches(patches []Patch, basePath string) error {
	validOps := []string{"add", "remove", "replace", "move", "copy", "test"}

	// Find the first validation error using lo.FindIndexOf
	invalidPatch, invalidIndex, found := lo.FindIndexOf(patches, func(patch Patch) bool {
		return patch.File == "" ||
			patch.Op == "" ||
			!lo.Contains(validOps, patch.Op) ||
			patch.Path == "" ||
			patch.ValueVariable == ""
	})

	if !found {
		// If basePath is provided, validate multi-document YAML files
		if basePath != "" {
			return validateMultiDocumentTargets(patches, basePath)
		}
		return nil // All patches are valid
	}

	// Determine specific error message
	switch {
	case invalidPatch.File == "":
		return fmt.Errorf("patch %d: file cannot be empty", invalidIndex)
	case invalidPatch.Op == "":
		return fmt.Errorf("patch %d: op cannot be empty", invalidIndex)
	case !lo.Contains(validOps, invalidPatch.Op):
		return fmt.Errorf("patch %d: invalid op '%s', must be one of: %s",
			invalidIndex, invalidPatch.Op, strings.Join(validOps, ", "))
	case invalidPatch.Path == "":
		return fmt.Errorf("patch %d: path cannot be empty", invalidIndex)
	case invalidPatch.ValueVariable == "":
		return fmt.Errorf("patch %d: valueVariable cannot be empty", invalidIndex)
	}

	return nil
}

// ResolvePatches returns the RFC 6902 patches that the manifest requests with the valueVariables
// replaced with their provided values.
func ResolvePatches(manifest *Manifest, vars map[string]string) (map[string][]ResolvedPatch, error) {
	if undefinedVar, found := lo.Find(manifest.Patches, func(p Patch) bool {
		return !lo.HasKey(vars, p.ValueVariable)
	}); found {
		return nil, fmt.Errorf("undefined variable: %s", undefinedVar.ValueVariable)
	}

	// Build the patches map using lo.Reduce
	patches := lo.Reduce(manifest.Patches, func(acc map[string][]ResolvedPatch, p Patch, _ int) map[string][]ResolvedPatch {
		val := vars[p.ValueVariable]

		// Use YAML unmarshaling to convert the value string to its appropriate type (e.g., int, bool, object)
		// for JSON Patch operations. This ensures that values like "true", "42", or "{foo: bar}" are
		// interpreted as booleans, numbers, or objects, not just strings. If unmarshaling fails,
		// fall back to treating the value as a raw string.
		var patchValue any
		if err := yaml.Unmarshal([]byte(val), &patchValue); err != nil {
			patchValue = val
		}

		patch := ResolvedPatch{
			Target: p.Target,
			Patch: RFC6902Patch{
				Op:    p.Op,
				Path:  p.Path,
				Value: patchValue,
			},
		}

		acc[p.File] = append(acc[p.File], patch)
		return acc
	}, make(map[string][]ResolvedPatch))

	return patches, nil
}

// validateMultiDocumentTargets validates that patches for multi-document YAML files have explicit document targets.
func validateMultiDocumentTargets(patches []Patch, basePath string) error {
	patchesByFile := lo.GroupBy(patches, func(patch Patch) string {
		return patch.File
	})

	for relPath, filePatches := range patchesByFile {
		filePath := filepath.Join(basePath, relPath)
		fileContent, err := os.ReadFile(filepath.Clean(filePath))
		if err != nil {
			// If file doesn't exist during validation, skip the multi-doc check
			// The file read error will be caught later during actual patching
			continue
		}

		// Split by YAML separator to count documents
		docStrings := strings.Split(strings.TrimSpace(string(fileContent)), "---")

		nonEmptyDocs := lo.Filter(docStrings, func(doc string, _ int) bool {
			return strings.TrimSpace(doc) != ""
		})

		// If file has multiple documents, validate that all patches have explicit targets
		if len(nonEmptyDocs) > 1 {
			untargetedPatches := lo.Filter(filePatches, func(patch Patch, _ int) bool {
				return patch.Target == nil || patch.Target.DocumentIndex == nil
			})

			if len(untargetedPatches) > 0 {
				return fmt.Errorf("file %s contains %d documents but has %d patches without explicit document targets - please specify 'target.documentIndex' for multi-document files",
					relPath, len(nonEmptyDocs), len(untargetedPatches))
			}
		}
	}

	return nil
}

