import { PrismaClient } from "@/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url || url.trim() === "") {
    throw new Error("DATABASE_URL environment variable is not set or is empty.");
  }
  return url;
}

const DEFAULT_PG_POOL_MAX = 20;
const DEFAULT_PG_POOL_IDLE_TIMEOUT_MS = 30000;
const DEFAULT_PG_POOL_CONNECTION_TIMEOUT_MS = 5000;

const _pgPoolMax = Number.parseInt(process.env.PG_POOL_MAX ?? "", 10);
const PG_POOL_MAX = Number.isNaN(_pgPoolMax) ? DEFAULT_PG_POOL_MAX : _pgPoolMax;

const _pgPoolIdleTimeout = Number.parseInt(process.env.PG_POOL_IDLE_TIMEOUT_MS ?? "", 10);
const PG_POOL_IDLE_TIMEOUT_MS = Number.isNaN(_pgPoolIdleTimeout) ? DEFAULT_PG_POOL_IDLE_TIMEOUT_MS : _pgPoolIdleTimeout;

const _pgPoolConnectionTimeout = Number.parseInt(process.env.PG_POOL_CONNECTION_TIMEOUT_MS ?? "", 10);
const PG_POOL_CONNECTION_TIMEOUT_MS = Number.isNaN(_pgPoolConnectionTimeout) ? DEFAULT_PG_POOL_CONNECTION_TIMEOUT_MS : _pgPoolConnectionTimeout;

function createPrismaClient() {
  const adapter = new PrismaPg({
    connectionString: getDatabaseUrl(),
    max: PG_POOL_MAX,
    idleTimeoutMillis: PG_POOL_IDLE_TIMEOUT_MS,
    connectionTimeoutMillis: PG_POOL_CONNECTION_TIMEOUT_MS,
  });
  return new PrismaClient({
    adapter,
    log:
      process.env.NODE_ENV === "development"
        ? ["query", "warn"]
        : ["error"],
  });
}

export const prisma = globalForPrisma.prisma ?? createPrismaClient();

if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

